<script setup lang="ts">
import { computed } from 'vue'
import ExploreFrame from './ExploreFrame.vue'
import { useExperience } from './use-experience'
import { lifeContexts,clothingItems,crossRoad,observeRoad,packItems,selectLife,submitLife,waitTraffic,waitRoad,weatherOutfits } from './daily-life'
const props=defineProps<{storageKey?:string}>()
const {save,frame,feedback,resetOpen,act,undo,requestReset,reset,hint}=useExperience(props,'daily-life')
const round=computed(()=>save.value.round),weather=computed(()=>weatherOutfits[round.value.weather])
const rules=['对照清单整理书包。点一下放入，再点一下取出，检查后进入下一步。','看看今天的天气，选择三件适合出门的衣物。','在模拟路口等行人绿灯，观察左右两侧，确认车辆停稳后和大人一起走斑马线。']
function submit(){const result=act(()=>submitLife(round.value));if(result)feedback.value=result.text}
function cross(){const result=act(()=>crossRoad(round.value));if(result)feedback.value=result.text}
function observe(side:number){act(()=>observeRoad(round.value,side));feedback.value=round.value.light==='green' && round.value.traffic?.[side]?'这一侧还有车辆未停稳，继续在路边等待，之后重新观察。':round.value.light==='green'?'这一侧的车辆已停稳，也要检查另一侧。':'车辆正在通行，先等行人绿灯，再重新观察两侧。'}
</script>
<template>
  <ExploreFrame v-bind="frame" :progress="`出门准备 ${Math.min(round.phase,3)} / 3 步`" :rules="rules" @difficulty="requestReset" @undo="undo" @restart="requestReset()" @reset="reset" @cancel="resetOpen=false" @hint="hint(round.phase===0?'按清单逐一检查，玩具和游戏机今天不用放进书包。':round.phase===1?weather.reason:'先等行人绿灯，然后分别观察左侧和右侧，再和大人一起走斑马线。')">
    <div class="life-steps"><span v-for="(name,index) in ['整理书包','看看天气','安全过街']" :key="name" :class="{active:round.phase===index,done:round.phase>index}">{{ round.phase>index?'✓':index+1 }} · {{ name }}</span></div>
    <template v-if="round.phase===0"><div class="life-scene life-backpack"><span>🎒</span><h2>{{ round.context===undefined?'今天的书包装什么？':lifeContexts[round.context].name }}</h2><p>不同活动需要不同用品，对照今天的清单做好准备。</p></div><div class="explore-checklist"><span v-for="id in round.required" :key="id" :class="{done:round.packed.includes(id)}">{{ packItems.find(item=>item.id===id)?.name }} {{ round.packed.includes(id)?'✓':'' }}</span></div><div class="explore-cards"><button v-for="item in packItems" :key="item.id" :class="['explore-card',{selected:round.packed.includes(item.id)}]" :aria-label="'书包物品 '+item.name" :aria-pressed="round.packed.includes(item.id)" @click="act(()=>selectLife(round,'pack',item.id))"><span>{{ item.icon }}</span>{{ item.name }}<small>{{ round.packed.includes(item.id)?'已放入':'点一下放入' }}</small></button></div><div class="life-next"><button class="explore-primary" @click="submit">检查书包</button></div></template>
    <template v-else-if="round.phase===1"><div class="life-scene life-weather"><span>{{ weather.icon }}</span><h2>{{ weather.name }}</h2><p>选择三件适合出门的物品。</p></div><div class="explore-cards"><button v-for="item in clothingItems" :key="item.id" :class="['explore-card',{selected:round.clothes.includes(item.id)}]" :aria-label="'出门衣物 '+item.name" :aria-pressed="round.clothes.includes(item.id)" @click="act(()=>selectLife(round,'clothes',item.id))"><span>{{ item.icon }}</span>{{ item.name }}<small>{{ round.clothes.includes(item.id)?'已选好':'点一下选择' }}</small></button></div><div class="life-next"><button class="explore-primary" @click="submit">准备出门</button></div></template>
    <template v-else><div class="life-road" :class="{green:round.light==='green',crossed:round.crossed}"><span class="life-traffic"><i :class="{lit:round.light==='red'}"></i><i :class="{lit:round.light==='green'}"></i><small>行人信号灯</small></span><span class="life-crosswalk"></span><span :class="{waiting:round.traffic?.[0]}" class="life-car car-left">🚙</span><span :class="{waiting:round.traffic?.[1]}" class="life-car car-right">🚗</span><span class="life-walkers">🚶🧑</span></div><p class="explore-caption">{{ round.light==='red'?'红灯时，行人在路边等待。':'行人绿灯亮了，确认两侧车辆都停稳后再通行。' }}</p><div v-if="!round.finished" class="life-road-controls"><button :disabled="round.light==='green'" class="explore-secondary" @click="act(()=>waitRoad(round));feedback='行人绿灯亮了，重新观察两侧车辆。'">等行人绿灯</button><button v-if="round.light==='green' && round.traffic?.some(Boolean)" class="explore-secondary" @click="act(()=>waitTraffic(round));feedback='车辆停稳了，重新确认左右两侧再通行。'">等车辆停稳</button><button class="explore-secondary" :disabled="round.looked.includes(0)" @click="observe(0)">观察左侧</button><button class="explore-secondary" :disabled="round.looked.includes(1)" @click="observe(1)">观察右侧</button><button class="explore-primary" @click="cross">和大人一起过街</button></div><div class="explore-checklist"><span :class="{done:round.light==='green'}">行人绿灯</span><span :class="{done:round.looked.includes(0) && round.light==='green'}">左侧车辆停稳</span><span :class="{done:round.looked.includes(1) && round.light==='green'}">右侧车辆停稳</span></div></template>
  </ExploreFrame>
</template>
<style scoped>
.life-road.green .life-car.waiting{animation:road-car 4s linear infinite}
.life-steps{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:22px}.life-steps span{font-size:11px;border:1px solid #d5e0c9;background:#fff;border-radius:20px;padding:8px 11px;color:#8e9b82}.life-steps .active{background:#f7ebd3;border-color:#d9bf8a;color:#9b8459}.life-steps .done{background:#e0edd7;color:#63875c}.life-scene{padding:25px;border-radius:15px;border:1px solid #ded9c5;background:#f4ecda;text-align:center;margin-bottom:23px}.life-scene>span{display:block;font-size:64px;margin-bottom:13px}.life-scene h2{font-size:21px;font-weight:650;color:#8c805f}.life-scene p{font-size:12px;margin-top:10px;color:#9b957c;line-height:1.9}.life-weather{background:#e7eff6;border-color:#d3e0e8}.life-weather h2{color:#7794a2}.life-next{display:flex;justify-content:center;margin-top:24px}.life-road{position:relative;height:300px;border:1px solid #d3ded0;border-radius:17px;overflow:hidden;background:linear-gradient(#e4e8d6 0%,#e4e8d6 24%,#acb7b9 24%,#acb7b9 78%,#e2e8d2 78%)}.life-crosswalk{position:absolute;left:44%;top:24%;bottom:22%;width:18%;background:repeating-linear-gradient(0deg,transparent 0,transparent 12px,#f9f9eb 12px,#f9f9eb 25px)}.life-traffic{position:absolute;left:23%;top:8%;display:flex;gap:7px;border:4px solid #768c7d;border-radius:8px;padding:5px;background:#667c6c}.life-traffic i{width:15px;height:15px;background:#9aa18a;border-radius:50%}.life-traffic i:first-child.lit{background:#e89c87}.life-traffic i:nth-child(2).lit{background:#badb8b}.life-traffic small{position:absolute;top:-23px;left:-3px;font-size:9px;white-space:nowrap;color:#8a977b}.life-car{position:absolute;font-size:42px;animation:road-car 4s linear infinite}.car-left{top:29%;left:5%}.car-right{top:52%;right:7%;animation-direction:reverse}.life-road.green .life-car{animation:none}.life-road.green .car-left{left:13%}.life-road.green .car-right{right:9%}.life-walkers{position:absolute;font-size:30px;left:43%;bottom:7%;transition:transform 1.4s}.life-road.crossed .life-walkers{transform:translateY(-235px)}.life-road-controls{display:flex;flex-wrap:wrap;gap:9px;justify-content:center;margin:22px 0}.life-road-controls button{font-size:12px}@keyframes road-car{0%{transform:translateX(-20px)}100%{transform:translateX(180px)}}@media(max-width:560px){.life-steps{gap:6px}.life-steps span{font-size:9px;padding:7px 9px}.life-scene{padding:23px 15px}.life-scene h2{font-size:19px}.life-road-controls{gap:7px}.life-road-controls button{font-size:11px;padding:10px 11px}.life-car{font-size:35px}.life-walkers{font-size:26px}.life-traffic{left:14%}}@media(prefers-reduced-motion:reduce){.life-car{animation:none}.life-walkers{transition:none}}
</style>
